css:
.print-format {
    padding: 0 !important;
    margin:0 !important;
    margin-top:0;
    margin-bottom:0;
    margin-left:0;
    margin-right:0;
    page-size:A4;
}

.voucher-sheet {
    font-family: Arial,sans-serif;
}

.voucher-card {
    box-sizing:border-box;
    display:inline-block;
    vertical-align:top;
    width:85.6mm;
    height:54mm;
    margin:2mm;
    padding:3mm;
    border:1px dashed #8e99aa;
    border-radius:3mm;
    background:#f5f8fc;
    color:#172e50;
    page-break-inside:avoid;
    overflow:hidden;
}

.voucher-brand {
    font-size:10px;
    font-weight:bold;
    height:5mm;
}

.voucher-brand img {
    max-height:5mm;
    max-width:20mm;
    margin-right:2mm;
}

.voucher-title {
    font-size:10px;
    letter-spacing:2px;
}

.voucher-value {
    font-size:19px;
    font-weight:bold;
    white-space:nowrap;
}

.voucher-barcode {
    float:right;
}

.voucher-barcode img {
    width:15mm;
    height:15mm;
}

.voucher-code {
    font-family:monospace;
    font-size:8px;
}

.voucher-dates,.voucher-pending {
    font-size:8px;
}

.voucher-eligibility,.voucher-terms {
    font-size:7px;
    line-height:1.2;
}

@page {
    size:A4;
    margin:8mm;
}
